#include <stdio.h>

static long long grid[1002][1002];

int main(void)
{
    int n, m, updates, queries;
    scanf("%d%d%d%d", &n, &m, &updates, &queries);
    for (int i = 0; i < updates; ++i) {
        int a, b, c, d;
        long long value;
        scanf("%d%d%d%d%lld", &a, &b, &c, &d, &value);
        grid[a][b] += value;
        grid[a][d + 1] -= value;
        grid[c + 1][b] -= value;
        grid[c + 1][d + 1] += value;
    }
    for (int pass = 0; pass < 2; ++pass)
        for (int i = 1; i <= n; ++i)
            for (int j = 1; j <= m; ++j)
                grid[i][j] += grid[i-1][j] + grid[i][j-1] - grid[i-1][j-1];
    for (int i = 0; i < queries; ++i) {
        int a, b, c, d;
        scanf("%d%d%d%d", &a, &b, &c, &d);
        printf("%lld\n", grid[c][d] - grid[a-1][d] - grid[c][b-1] + grid[a-1][b-1]);
    }
    return 0;
}

#include <stdio.h>

static int values[200000];

int main(void)
{
    int n;
    long long target;
    scanf("%d%lld", &n, &target);
    for (int i = 0; i < n; ++i) scanf("%d", &values[i]);
    int left = 0, best = n + 1;
    long long sum = 0;
    for (int right = 0; right < 2 * n; ++right) {
        sum += values[right % n];
        if (right - left + 1 > n) sum -= values[left++ % n];
        while (sum >= target) {
            int length = right - left + 1;
            if (length < best) best = length;
            sum -= values[left++ % n];
        }
    }
    printf("%d\n", best <= n ? best : -1);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct { int start, end, reward; } Task;
static Task tasks[200001];
static long long best[200001];

static int by_end(const void *left, const void *right)
{
    const Task *a = left, *b = right;
    return (a->end > b->end) - (a->end < b->end);
}

int main(void)
{
    int n;
    scanf("%d", &n);
    for (int i = 1; i <= n; ++i)
        scanf("%d%d%d", &tasks[i].start, &tasks[i].end, &tasks[i].reward);
    qsort(tasks + 1, n, sizeof tasks[0], by_end);
    for (int i = 1; i <= n; ++i) {
        int lo = 0, hi = i - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo + 1) / 2;
            if (tasks[mid].end <= tasks[i].start) lo = mid;
            else hi = mid - 1;
        }
        long long take = best[lo] + tasks[i].reward;
        best[i] = take > best[i - 1] ? take : best[i - 1];
    }
    printf("%lld\n", best[n]);
    return 0;
}

#include <limits.h>
#include <stdio.h>

#define MAXN 600
#define INF (LLONG_MAX / 4)
static int weight[MAXN][MAXN];
static long long dist[2 * MAXN];
static int visited[2 * MAXN];

int main(void)
{
    int n, m, start, finish;
    scanf("%d%d%d%d", &n, &m, &start, &finish);
    for (int a = 0; a < n; ++a)
        for (int b = 0; b < n; ++b) weight[a][b] = -1;
    for (int i = 0; i < m; ++i) {
        int a, b, w;
        scanf("%d%d%d", &a, &b, &w);
        if (weight[a][b] < 0 || w < weight[a][b]) weight[a][b] = w;
    }
    for (int i = 0; i < 2 * n; ++i) dist[i] = INF;
    dist[start] = 0;
    for (int i = 0; i < 2 * n; ++i) {
        int state = -1;
        for (int j = 0; j < 2 * n; ++j)
            if (!visited[j] && (state < 0 || dist[j] < dist[state])) state = j;
        if (state < 0 || dist[state] == INF) break;
        visited[state] = 1;
        int a = state % n, layer = state - a;
        for (int b = 0; b < n; ++b) {
            int w = weight[a][b];
            if (w < 0) continue;
            long long full = dist[state] + w;
            if (full < dist[b + layer]) dist[b + layer] = full;
            long long reduced = dist[state] + w / 2;
            if (layer == 0 && reduced < dist[b + n]) dist[b + n] = reduced;
        }
    }
    long long answer = dist[finish] < dist[finish + n] ? dist[finish] : dist[finish + n];
    printf("%lld\n", answer == INF ? -1LL : answer);
    return 0;
}
